# versioner CHANGELOG.md generation
#
# Walks the full reachable history (topological, oldest first) and groups
# conventional commits under the version computed AT that commit: a bump
# commit opens a new section; no-bump commits join the section that is
# current. Non-conventional and ignored commits are omitted.
# Newest section first. Regenerated whole each time — do not edit by hand.

changelog_generate() {
	local ref="${1:-HEAD}" out_file="${2:-CHANGELOG.md}"
	local vma=0 vmin=0 vpat=0 cur_ver="0.0.0" cur_date="" cur_entries=""
	local -a sections=()
	local out h date msg header scope subject breaking entry newv
	local i rec sv sd se

	git rev-parse -q --verify "${ref}^{commit}" >/dev/null || {
		printf 'versioner: unknown ref: %s\n' "$ref" >&2
		return 1
	}
	out="$(git log --topo-order --reverse --date=short --format='%H%x01%ad%x01%B%x02' "$ref")" || return 1
	while [ -n "$out" ]; do
		h="${out%%$'\x01'*}"
		out="${out#*$'\x01'}"
		date="${out%%$'\x01'*}"
		out="${out#*$'\x01'}"
		msg="${out%%$'\x02'*}"
		if [[ "$out" == *$'\x02'* ]]; then
			out="${out#*$'\x02'}"
		else
			out=""
		fi
		header="${msg%%$'\n'*}"
		if config_is_ignored "$header"; then
			continue
		fi
		if ! parse_bump "$header" "$msg"; then
			continue
		fi
		scope="$BUMP_SCOPE"
		subject="$BUMP_SUBJECT"
		breaking="$BUMP_BREAKING"
		case "${BUMP_LEVEL:-}" in
		major)
			vma=$((vma + 1))
			vmin=0
			vpat=0
			;;
		minor)
			vmin=$((vmin + 1))
			vpat=0
			;;
		patch) vpat=$((vpat + 1)) ;;
		esac
		newv="${vma}.${vmin}.${vpat}"
		if [ "$newv" != "$cur_ver" ]; then
			if [ -n "$cur_entries" ]; then
				sections+=("${cur_ver}"$'\x1f'"${cur_date}"$'\x1f'"${cur_entries}")
			fi
			cur_ver="$newv"
			cur_entries=""
			cur_date=""
		fi
		entry="- ${BUMP_TYPE}"
		if [ -n "$scope" ]; then
			entry="${entry}(${scope})"
		fi
		entry="${entry}: ${subject} (${h:0:$HASH_LEN})"
		if [ "$breaking" = 1 ]; then
			entry="${entry} **BREAKING**"
		fi
		cur_entries="${cur_entries}${entry}"$'\n'
		cur_date="$date"
	done
	if [ -n "$cur_entries" ]; then
		sections+=("${cur_ver}"$'\x1f'"${cur_date}"$'\x1f'"${cur_entries}")
	fi
	{
		echo '# Changelog'
		echo
		echo "_Generated by versioner on $(date +%Y-%m-%d). Conventional commits only; do not edit by hand._"
		for ((i = ${#sections[@]} - 1; i >= 0; i--)); do
			rec="${sections[$i]}"
			sv="${rec%%$'\x1f'*}"
			rec="${rec#*$'\x1f'}"
			sd="${rec%%$'\x1f'*}"
			se="${rec#*$'\x1f'}"
			echo
			echo "## ${sv} - ${sd}"
			echo
			printf '%s' "$se"
		done
	} >"$out_file"
}
